def ico(name):
    paths = {
        'word': '<path d="M6 3h9l4 4v14H6z M14 3v5h5 M8 12l2 6 2-4 2 4 2-6"/>',
        'posta': '<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m3 6 9 7 9-7"/>',
        'halley': '<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 9h18 M9 9v11 M13 12h5 M13 16h5"/>',
        'sessione': '<rect x="3" y="3" width="18" height="13" rx="2"/><path d="M8 21h8 M12 16v5"/>',
        'riunione': '<circle cx="8" cy="8" r="3"/><circle cx="17" cy="9" r="2"/><path d="M2 21v-4c0-5 12-5 12 0v4 M16 14c4 0 6 2 6 5"/>',
        'telefonata': '<path d="m5 3 4 4-2 3c2 4 3 5 7 7l3-2 4 4c-4 7-12-1-15-5S0 5 5 3z"/>',
        'ai': '<path d="m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3z"/>',
        'check': '<path d="m4 12 5 5L20 5"/>',
        'plus': '<path d="M12 4v16 M4 12h16"/>',
        'pause': '<path d="M8 4v16 M16 4v16"/>',
        'alert': '<path d="m12 3 10 18H2z M12 9v5 M12 17v1"/>',
        'pdf': '<path d="M6 3h9l4 4v14H6z M14 3v5h5 M9 13h7 M9 17h7"/>',
        'arrow': '<path d="M4 12h16 m-6-6 6 6-6 6"/>',
    }
    return f'<svg class="symbol" viewBox="0 0 24 24" aria-hidden="true">{paths[name]}</svg>'

def chip(name, text, origin='auto'):
    return f'<span class="signal {origin}">{ico(name)}{text}<span class="source">'+('Rilevato' if origin=='auto' else 'Dichiarato' if origin=='declared' else 'Testo AI')+'</span></span>'

